import { useEffect, useMemo, useState } from 'react';

type VariationOption = { name: string; priceDelta: number; imageUrl?: string };
type VariationGroup = { name: string; options: VariationOption[] };
type VariationOptionDraft = { id: string; name: string; priceDelta: string; imageUrl: string; imageFile: File | null };
type VariationGroupDraft = { id: string; name: string; options: VariationOptionDraft[] };
type ProductKind = 'notebook' | 'pens' | 'markers' | 'notes' | 'pouch' | 'brush';
type Product = { id: number; name: string; detail: string; oldPrice: number; price: number; tag?: string; kind: ProductKind; imageUrl?: string; category?: string; stock?: number; productionDeadline?: string; needsArtworkApproval?: boolean; productionTypeId?: string; favorites?: number; rating?: number; reviews?: ProductReview[]; variationGroups?: VariationGroup[] };

type ProductReview = {
  name: string;
  rating: number;
  comment: string;
  createdAt: string;
};
type CategoryBanner = { title: string; text: string; imageUrl: string; imageFile: File | null };
type CartItem = Product & { quantity: number; selectedVariations?: Record<string, VariationOption>; finalPrice?: number; personalizationName?: string; notes?: string };
type Customer = { name: string; email: string; phone: string; address: string; city: string; state: string };
type AccountForm = Customer & { password: string; confirmPassword: string };
type LoginForm = { email: string; password: string };
type ProductionTaskKey = string;
type ProductionTasks = Record<ProductionTaskKey, boolean>;
type ProductionType = { id: string; name: string; steps: { key: string; label: string }[] };
type ArtworkApproval = { required: boolean; imageUrl?: string; status: 'nao_enviada' | 'aguardando_cliente' | 'aprovada' | 'devolvida'; clientNote?: string; updatedAt?: string };
type OrderItem = { id: number; name: string; detail: string; price: number; quantity: number; subtotal: number; selectedVariations?: Record<string, VariationOption>; personalizationName?: string; notes?: string; productionDeadline?: string; productionTypeId?: string; productionTypeName?: string; productionSteps?: { key: string; label: string }[]; productionTasks?: ProductionTasks; artwork?: ArtworkApproval };
type ProductionStage = 'pagamento aprovado' | 'arte aprovada' | 'impressao' | 'montagem' | 'embalagem' | 'envio entrega';
type Order = { id: string; customer_email: string | null; customer_name: string | null; customer_phone: string | null; items: OrderItem[]; total: number; status: string; created_at: string; production_deadline?: string; desired_date?: string; tracking_code?: string; order_number?: number; artwork_status?: string; production_stage?: ProductionStage; priority?: 'normal' | 'alta' | 'urgente' };
type AdminCustomer = Customer & { id?: string; created_at?: string };
type Coupon = {
  code: string;
  discount: number;
  type: 'percent' | 'fixed';
  expiresAt: string;
  minimumValue: number;
  usageLimit: number;
  used: number;
  active: boolean;
};
type IconName = 'truck' | 'shield' | 'card' | 'gift' | 'chat' | 'heart' | 'home' | 'instagram' | 'search' | 'cart' | 'user' | 'bag';

const PINK = '#F34288';
const ORANGE = '#F06F11';
const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL || '';
const SUPABASE_ANON_KEY = import.meta.env.VITE_SUPABASE_ANON_KEY || '';
const ADMIN_EMAILS = (import.meta.env.VITE_ADMIN_EMAILS || 'mariacampos.nq@gmail.com').split(',').map((email: string) => email.trim().toLowerCase()).filter(Boolean);

