  function cancelEditProduct() { setEditingProductId(null); setProductForm({ name: '', detail: '', oldPrice: '', price: '', stock: '', productionDeadline: '5 a 7 dias úteis', needsArtworkApproval: true, productionTypeId: 'personalizados', tag: '', kind: 'notebook', category: 'Planners', imageFile: null }); setVariationDrafts([createEmptyVariationGroup()]); }
