  function updateVariationGroupName(groupId: string, name: string) { setVariationDrafts((c) => c.map((g) => (g.id === groupId ? { ...g, name } : g))); }
  function addVariationOption(groupId: string) { setVariationDrafts((c) => c.map((g) => g.id === groupId ? { ...g, options: [...g.options, { id: uid(), name: '', priceDelta: '0', imageUrl: '', imageFile: null }] } : g)); }
  function removeVariationOption(groupId: string, optionId: string) { setVariationDrafts((c) => c.map((g) => g.id === groupId ? { ...g, options: g.options.filter((o) => o.id !== optionId) } : g)); }
