  function createProductionType() {
    const name = productionTypeForm.name.trim();
    const steps = productionTypeForm.steps.split(',').map((step) => step.trim()).filter(Boolean).map((label) => ({ key: label.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-'), label }));
    if (!name) return showMessage('Informe o nome do tipo de produção.');
    setProductionTypes((current) => [...current, { id: name.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-'), name, steps }]);
    setProductionTypeForm({ name: '', steps: '' });
    showMessage('Tipo de produção criado.');
  }

  function getProductionType(product: Product) {
    return productionTypes.find((type) => type.id === product.productionTypeId) || productionTypes.find((type) => type.id === 'personalizados') || productionTypes[0];
  }

