  function validateCoupon(code: string) {
    const normalizedCode = code.trim().toUpperCase();
    const coupon = couponManager.find((item) => item.code === normalizedCode);

    if (!coupon || !coupon.active) return { ok: false, message: 'Cupom inválido ou inativo.', coupon: null as Coupon | null };
    if (coupon.expiresAt && new Date(coupon.expiresAt + 'T23:59:59') < new Date()) return { ok: false, message: 'Esse cupom está vencido.', coupon: null as Coupon | null };
    if (coupon.minimumValue > subtotal) return { ok: false, message: `Pedido mínimo de ${money(coupon.minimumValue)} para usar esse cupom.`, coupon: null as Coupon | null };
    if (coupon.usageLimit > 0 && coupon.used >= coupon.usageLimit) return { ok: false, message: 'Esse cupom atingiu o limite de uso.', coupon: null as Coupon | null };

    return { ok: true, message: coupon.type === 'percent' ? `Cupom aplicado: ${coupon.discount}% OFF` : `Cupom aplicado: ${money(coupon.discount)} OFF`, coupon };
  }

  function applyCoupon() {
    const result = validateCoupon(couponCode);
    if (!result.ok || !result.coupon) {
      setAppliedCoupon(null);
      showMessage(result.message, 4200);
      return;
    }

    setAppliedCoupon({ code: result.coupon.code, type: result.coupon.type, value: result.coupon.discount });
    showMessage(result.message);
  }

  function saveCoupon() {
    const code = couponForm.code.trim().toUpperCase();
    const discountValue = Number(couponForm.discount.replace(',', '.'));
    const minimumValue = Number(couponForm.minimumValue.replace(',', '.') || 0);
    const usageLimit = Number(couponForm.usageLimit || 0);

    if (!code || !Number.isFinite(discountValue) || discountValue <= 0) return showMessage('Preencha código e desconto válido.');
    if (couponForm.type === 'percent' && discountValue > 100) return showMessage('Cupom em porcentagem não pode passar de 100%.');
    if (!editingCouponCode && couponManager.some((coupon) => coupon.code === code)) return showMessage('Já existe um cupom com esse código.');
    if (editingCouponCode && editingCouponCode !== code && couponManager.some((coupon) => coupon.code === code)) return showMessage('Já existe outro cupom com esse código.');

    if (editingCouponCode) {
      setCouponManager((current) => current.map((coupon) => coupon.code === editingCouponCode ? {
        ...coupon,
        code,
        discount: discountValue,
        type: couponForm.type,
        expiresAt: couponForm.expiresAt,
        minimumValue: Number.isFinite(minimumValue) ? minimumValue : 0,
        usageLimit: Number.isFinite(usageLimit) ? usageLimit : 0,
      } : coupon));
      if (appliedCoupon?.code === editingCouponCode) setAppliedCoupon(null);
      showMessage('Cupom atualizado com sucesso.');
    } else {
      setCouponManager((current) => [...current, {
        code,
        discount: discountValue,
        type: couponForm.type,
        expiresAt: couponForm.expiresAt,
        minimumValue: Number.isFinite(minimumValue) ? minimumValue : 0,
        usageLimit: Number.isFinite(usageLimit) ? usageLimit : 0,
        used: 0,
        active: true,
      }]);
      showMessage('Cupom criado com sucesso.');
    }

    setCouponForm({ code: '', discount: '', type: 'percent', expiresAt: '', minimumValue: '', usageLimit: '' });
    setEditingCouponCode(null);
  }

  function editCoupon(coupon: Coupon) {
    setEditingCouponCode(coupon.code);
    setCouponForm({
      code: coupon.code,
      discount: String(coupon.discount).replace('.', ','),
      type: coupon.type,
      expiresAt: coupon.expiresAt,
      minimumValue: String(coupon.minimumValue || ''),
      usageLimit: String(coupon.usageLimit || ''),
    });
  }

  function cancelCouponEdit() {
    setEditingCouponCode(null);
    setCouponForm({ code: '', discount: '', type: 'percent', expiresAt: '', minimumValue: '', usageLimit: '' });
  }

  function toggleCouponStatus(code: string) {
    setCouponManager((current) => current.map((coupon) => coupon.code === code ? { ...coupon, active: !coupon.active } : coupon));
  }

  function deleteCoupon(code: string) {
    setCouponManager((current) => current.filter((coupon) => coupon.code !== code));
    if (appliedCoupon?.code === code) setAppliedCoupon(null);
  }

