  async function updateOrderStatus(orderId: string, status: string) { try { const response = await fetch(`${SUPABASE_URL}/rest/v1/orders?id=eq.${orderId}`, { method: 'PATCH', headers: supabaseHeaders(authAccessToken, { 'Content-Type': 'application/json' }), body: JSON.stringify({ status }) }); if (!response.ok) throw new Error(await response.text()); setOrders((c) => c.map((o) => o.id === orderId ? { ...o, status } : o)); setMyOrders((c) => c.map((o) => o.id === orderId ? { ...o, status } : o)); showMessage(`Status atualizado para: ${status}.`); } catch (error) { console.error(error); showMessage('Não foi possível atualizar o status.'); } }
