  async function updateItemProduction(orderId: string, itemIndex: number, task: ProductionTaskKey, checked: boolean) {
    const targetOrder = orders.find((order) => order.id === orderId);
    if (!targetOrder) return;

    const updatedItems = targetOrder.items.map((item, index) => index === itemIndex ? {
      ...item,
      productionTasks: {
        ...(item.productionTasks || {}),
        [task]: checked,
      },
    } : item);

    try {
      const response = await fetch(`${SUPABASE_URL}/rest/v1/orders?id=eq.${orderId}`, {
        method: 'PATCH',
        headers: supabaseHeaders(authAccessToken, { 'Content-Type': 'application/json' }),
        body: JSON.stringify({ items: updatedItems }),
      });
      if (!response.ok) throw new Error(await response.text());
      setOrders((current) => current.map((order) => order.id === orderId ? { ...order, items: updatedItems } : order));
      setMyOrders((current) => current.map((order) => order.id === orderId ? { ...order, items: updatedItems } : order));
    } catch (error) {
      console.error(error);
      showMessage('Não foi possível salvar a marcação da produção.');
    }
  }

  async function updateArtwork(orderId: string, itemIndex: number, artwork: ArtworkApproval) {
    const targetOrder = orders.find((order) => order.id === orderId);
    if (!targetOrder) return;
    const updatedItems = targetOrder.items.map((item, index) => index === itemIndex ? { ...item, artwork } : item);
    try {
      const response = await fetch(`${SUPABASE_URL}/rest/v1/orders?id=eq.${orderId}`, {
        method: 'PATCH',
        headers: supabaseHeaders(authAccessToken, { 'Content-Type': 'application/json' }),
        body: JSON.stringify({ items: updatedItems }),
      });
      if (!response.ok) throw new Error(await response.text());
      setOrders((current) => current.map((order) => order.id === orderId ? { ...order, items: updatedItems } : order));
      setMyOrders((current) => current.map((order) => order.id === orderId ? { ...order, items: updatedItems } : order));
      showMessage('Arte atualizada.');
    } catch (error) {
      console.error(error);
      showMessage('Não foi possível salvar a arte.');
    }
  }

  async function uploadArtwork(orderId: string, itemIndex: number, file: File | null) {
    if (!file) return;
    const imageUrl = await uploadImageOrDataUrl(file, `arte-${orderId}-${itemIndex}`, authAccessToken);
    const order = orders.find((item) => item.id === orderId);
    const currentArtwork = order?.items?.[itemIndex]?.artwork || { required: true, status: 'nao_enviada' as const };
    updateArtwork(orderId, itemIndex, { ...currentArtwork, imageUrl, status: 'aguardando_cliente', updatedAt: new Date().toISOString() });
  }

  async function clientRespondArtwork(orderId: string, itemIndex: number, approved: boolean) {
    const order = myOrders.find((item) => item.id === orderId) || orders.find((item) => item.id === orderId);
    const currentArtwork = order?.items?.[itemIndex]?.artwork;
    if (!currentArtwork) return;
    const note = approved ? '' : window.prompt('O que precisa ajustar na arte?') || '';
    await updateArtwork(orderId, itemIndex, { ...currentArtwork, status: approved ? 'aprovada' : 'devolvida', clientNote: note, updatedAt: new Date().toISOString() });
  }

  function productionProgress(item: OrderItem) {
    const steps = item.productionSteps?.length ? item.productionSteps : productionTasks;
    if (!steps.length) return 100;
    const tasks = item.productionTasks || {};
    const done = steps.filter((task) => tasks[task.key]).length;
    return Math.round((done / steps.length) * 100);
  }
